# ── Matplotlib Plot Helpers with Transparent Background ───────────────────────
def make_metric_bar(values, labels, colors=None, percent=True):
    is_d = st.session_state.get("dark_mode", False)
    t_color = "#e2eaf8" if is_d else "#17243c"
    lbl_color = "#94a3b8" if is_d else "#5a6b84"
    grid_color = "#334155" if is_d else "#cbd5e1"

    fig, ax = plt.subplots(figsize=(3.4, 2.5))
    fig.patch.set_alpha(0)
    ax.set_facecolor("none")
    if colors is None:
        colors = ["#5B8DEF", "#1685F8", "#20B66A"]
    bars = ax.bar(range(len(values)), values, color=colors, width=0.55,
                  edgecolor="none", alpha=0.9, zorder=3)
    for bar, v in zip(bars, values):
        txt = f"{v:.2%}" if percent else f"{v:.4f}"
        ax.text(bar.get_x() + bar.get_width()/2, bar.get_height() + 0.015,
                txt, ha="center", va="bottom", fontsize=8.2, fontweight=800,
                color=t_color)
    ax.set_xticks(range(len(labels)))
    short = [MODEL_SHORT.get(l, l) for l in labels]
    ax.set_xticklabels(short, fontsize=7.2, fontweight=600, color=lbl_color)
    ax.spines[["top","right"]].set_visible(False)
    ax.spines[["bottom","left"]].set_color(grid_color)
    ax.grid(axis="y", alpha=0.35, color=grid_color, zorder=0)
    ax.tick_params(axis="y", labelsize=7.5, colors=lbl_color)
    if percent:
        ax.yaxis.set_major_formatter(mticker.PercentFormatter(1.0))
        ax.set_ylim(0, max(values) * 1.25 if max(values) > 0 else 1.0)
    else:
        ax.set_ylim(0, max(values) * 1.25 if max(values) > 0 else 1.0)
    fig.tight_layout()
    return fig

