def make_confusion_matrix(cm, title="", active_cell=None):
    is_d = st.session_state.get("dark_mode", False)
    t_color = "#e2eaf8" if is_d else "#17243c"
    lbl_color = "#94a3b8" if is_d else "#5a6b84"

    fig, ax = plt.subplots(figsize=(2.5, 2.5))
    fig.patch.set_alpha(0)
    ax.set_facecolor("none")
    arr = np.asarray(cm)
    cmap = plt.cm.Blues
    im = ax.imshow(arr, cmap=cmap, aspect="auto", alpha=0.9)
    for (i, j), v in np.ndenumerate(arr):
        colour = "white" if v > arr.max() * 0.55 else t_color
        if active_cell is not None and active_cell == (i, j):
            is_right = (i == j)
            rect = plt.Rectangle((j - 0.46, i - 0.46), 0.92, 0.92, fill=False,
                                 edgecolor="#22c55e" if is_right else "#ef4444",
                                 linewidth=3.0, zorder=6)
            ax.add_patch(rect)
        ax.text(j, i, f"{int(v):,}", ha="center", va="center",
                fontsize=8.5, fontweight=700, color=colour, zorder=7)
    ax.set_xticks([0, 1])
    ax.set_xticklabels(CLASSES, fontsize=7.0, fontweight=600, color=lbl_color)
    ax.set_yticks([0, 1])
    ax.set_yticklabels(CLASSES, fontsize=7.0, fontweight=600, color=lbl_color)
    ax.set_xlabel("Predicted Label", fontsize=7.0, fontweight=600, color=lbl_color)
    ax.set_ylabel("True Label", fontsize=7.0, fontweight=600, color=lbl_color)
    ax.set_title(title, fontsize=8.0, fontweight=700, color=t_color, pad=5)
    cbar = fig.colorbar(im, ax=ax, fraction=0.046, pad=0.04)
    cbar.ax.tick_params(labelsize=6.0, colors=lbl_color)
    cbar.outline.set_visible(False)
    fig.tight_layout()
    return fig

def pil_to_base64_str(im: Image.Image, max_dim: int = 160) -> str:
    buffered = io.BytesIO()
    thumb = im.copy()
    resample_filter = getattr(getattr(Image, "Resampling", Image), "LANCZOS", Image.LANCZOS)
    thumb.thumbnail((max_dim, max_dim), resample_filter)
    thumb.convert("RGB").save(buffered, format="JPEG", quality=85)
    return base64.b64encode(buffered.getvalue()).decode("utf-8")

