@st.cache_data
def load_metadata():
    p = ROOT / "archive" / "waterbird_complete95_forest2water2" / "metadata.csv"
    if p.exists():
        try:
            return pd.read_csv(p)
        except Exception:
            return None
    return None

meta_df = load_metadata()

def lookup_metadata(fname):
    if meta_df is None or not fname:
        return None
    name_clean = Path(fname).name
    m = meta_df[meta_df["img_filename"].str.endswith(name_clean)]
    if not m.empty:
        return m.iloc[0].to_dict()
    stem = Path(fname).stem
    m = meta_df[meta_df["img_filename"].str.contains(stem, case=False, na=False)]
    if not m.empty:
        return m.iloc[0].to_dict()
    tokens = [t for t in stem.split("_") if t.isdigit() and len(t) >= 4]
    for tok in tokens:
        m = meta_df[meta_df["img_filename"].str.contains(tok, case=False, na=False)]
        if not m.empty:
            return m.iloc[0].to_dict()
    return None

def make_prob_chart(preds_dict):
    fig, ax = plt.subplots(figsize=(5.6, 2.9))
    fig.patch.set_alpha(0)
    ax.set_facecolor("none")
    n_classes = 2
    n_models  = len(preds_dict)
    bar_w     = 0.22
    indices   = np.arange(n_classes)
    colors = ["#ef6c7a", "#1e88e5", "#22c55e"]
    for i, (name, r) in enumerate(preds_dict.items()):
        probs = r["probs"]
        color = colors[i % len(colors)]
        bars = ax.bar(indices + i * bar_w, probs, bar_w,
                      label=LEGEND_SHORT.get(name, name),
                      color=color, edgecolor="none", alpha=0.9, zorder=3)
        for bar, v in zip(bars, probs):
            ax.text(bar.get_x() + bar.get_width()/2, bar.get_height() + 0.02,
                    f"{v:.1%}", ha="center", va="bottom", fontsize=7.5, fontweight=700,
                    color="#17243c")
    ax.set_xticks(indices + bar_w * (n_models - 1) / 2)
    ax.set_xticklabels(CLASSES, fontsize=8.2, fontweight=600, color="#5a6b84")
    ax.set_ylabel("Probability", fontsize=8.0, fontweight=600, color="#5a6b84")
    ax.set_ylim(0, 1.15)
    ax.yaxis.set_major_formatter(mticker.PercentFormatter(1.0))
    ax.spines[["top","right"]].set_visible(False)
    ax.spines[["bottom","left"]].set_color("#cbd5e1")
    ax.grid(axis="y", alpha=0.35, color="#cbd5e1", zorder=0)
    ax.legend(fontsize=7.0, frameon=False, loc="upper center", bbox_to_anchor=(0.5, 1.15), ncol=3)
    fig.tight_layout()
    return fig

